    EnTextos.textMensaTiempoAdelantoEntradasDeAireMenosm3,
    'यह वह समय है जब वेंटिलेशन बंद होने से पहले खिड़कियां बंद हो जाएंगी। यह समय न्यूनतम ऑफ टाइम (मेनू/कॉन्फ़िगरेशन/वेंटिलेशन/उन्नत) से अधिक नहीं हो सकता है और ब्रूडर चरण, S0 और प्राकृतिक चरण सहित सभी चरणों के न्यूनतम चक्र से कम नहीं हो सकता है।'
