    "एक यूएसबी स्टिक डालें, गंतव्य फ़ाइल को एक नाम निर्दिष्ट करें और निर्यात शुरू करने के लिए 'निर्यात' बटन दबाएँ। कॉन्फ़िगरेशन फ़ाइल USB मेमोरी के '/CTI/CFG/' फ़ोल्डर में सहेजी जाएगी।"
