    'पैरामीटर मान वक्र द्वारा इंजेक्ट किया जाता है, यदि आप इस पैरामीटर को बदलना चाहते हैं तो वक्र पर जाएं। (मुख्य कूलिंग / प्लस बटन / कर्व)'
