    "जब साइलो मोटर का डिजिटल इनपुट सक्रिय होता है, तो 'निगरानी समय' की गिनती शुरू हो जाती है, यदि इस दौरान 'वजन परिवर्तन' नहीं हुआ है, तो 'वाइब्रेटर रिले' को 'वाइब्रेटर समय' के लिए सक्रिय किया जाता है। जब यह समय बीत जाएगा, तो प्रक्रिया दोहराई जाएगी। जब सभी दोहराव पूरे हो जाएंगे, तो 'साइलो स्टॉप रिले' सक्रिय हो जाएगा और वाइब्रेटर चेतावनी प्रदर्शित होगी। संचालन फिर से शुरू करने के लिए, चेतावनियाँ साफ़ की जानी चाहिए।"
